            staleMdxEsmRecoveryAttempts.set(key, completedAt);
            staleMdxEsmRecoveryCompletedThrough.set(key, nextStaleMdxEsmRecoveryRequestSequence);
            pruneStaleMdxEsmRecoveryAttempts(completedAt);
